CREATE OR REPLACE FUNCTION public.new_audit_event_id()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  bytes bytea := substring(sha256(uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid())) FROM 1 FOR 16);
  alphabet constant text := 'abcdefghijklmnopqrstuvwxyz234567';
  encoded text := '';
  acc bigint := 0;
  bits integer := 0;
BEGIN
  FOR i IN 0..15 LOOP
    acc := (acc << 8) | get_byte(bytes, i);
    bits := bits + 8;
    WHILE bits >= 5 LOOP
      encoded := encoded || substr(alphabet, ((acc >> (bits - 5)) & 31)::integer + 1, 1);
      bits := bits - 5;
    END LOOP;
    acc := acc & ((1::bigint << bits) - 1);
  END LOOP;
  IF bits > 0 THEN
    encoded := encoded || substr(alphabet, ((acc << (5 - bits)) & 31)::integer + 1, 1);
  END IF;
  RETURN 'evt_' || encoded;
END $function$
